/* =========================================
   ZERIAFLUX - INYECCIÓN GLOBAL DE ESTILO
   ========================================= */

/* 1. Selección de texto (Fondo verde neón, texto oscuro) */
*::selection {
    background-color: #22c55e !important; 
    color: #0f0a1c !important; 
}

/* 2. Barra de desplazamiento corporativa */
::-webkit-scrollbar {
    width: 12px !important;
    background-color: #0f0a1c !important; /* Fondo morado Zeriaflux */
}

::-webkit-scrollbar-track {
    background-color: #0f0a1c !important;
}

::-webkit-scrollbar-thumb {
    background-color: #1e1533 !important; /* Morado un tono más claro */
    border: 1px solid #22c55e !important; /* Borde verde eléctrico */
    border-radius: 6px !important;
}

::-webkit-scrollbar-thumb:hover {
    background-color: #22c55e !important;
    box-shadow: 0 0 10px rgba(34, 197, 94, 0.5) !important;
}
